/* Een tekst op id, en de tekst van deze week: per niveau, vast voor iedereen
   in dezelfde ISO-week, zodat een docent kan zeggen "maak het dictee van deze
   week" en de hele klas dezelfde tekst krijgt. */
(function(D){
  'use strict';
  var NIV = { bb:1, kgt:2, hv:3 };
  D.WEEKZINNEN = 7;   /* zo lang is het dictee van de week */
  /* de vakthema's: een tekst met thema gaat over dat vak (t-mens-bb-01) */
  D.THEMAS = { mens:'Mens en maatschappij', geschiedenis:'Geschiedenis', aardrijkskunde:'Aardrijkskunde', biologie:'Biologie', economie:'Economie', wiskunde:'Wiskunde en rekenen', natuur:'Natuur en techniek' };
  D.themaVan = function(t){ return (t && (t.thema || t.tag)) || ''; };
  /* de titel in een keuzelijst: met het vak ervoor als de tekst een thema heeft */
  D.lijstTitel = function(t){ var th = t && t.thema; return (th && D.THEMAS[th] ? D.THEMAS[th] + ': ' : '') + ((t && t.titel) || ''); };
  D.STANDAARD = 10;   /* zo lang is een tekst uit de lijst als niemand een lengte koos */
  D.tekst = function(id){ return D.teksten.filter(function(t){ return t.id === id; })[0] || null; };
  D.isoWeek = function(datum){
    var d0 = datum instanceof Date ? datum : (datum ? new Date(datum) : new Date());
    var d = new Date(Date.UTC(d0.getFullYear(), d0.getMonth(), d0.getDate()));
    var dag = d.getUTCDay() || 7;
    d.setUTCDate(d.getUTCDate() + 4 - dag);
    var begin = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
    return { jaar: d.getUTCFullYear(), week: Math.ceil(((d - begin) / 86400000 + 1) / 7) };
  };
  /* Een tekst op een gekozen lengte (docent, dictee-rooster). Korter: de eerste
     zinnen. Langer, tot dertig: het dictee gaat verder met de volgende teksten van
     hetzelfde niveau, in dezelfde vaste volgorde als het dictee van de week. Het
     id blijft dat van de eerste tekst, zodat uitslagen bij elkaar blijven. */
  D.MAXZINNEN = 30;
  D.opLengte = function(t, n){
    if (!t || !n) return t;
    n = Math.min(D.MAXZINNEN, n);
    var heel = D.tekst(t.id) || t;
    if (heel.zinnen.length >= n) return Object.assign({}, heel, { zinnen: heel.zinnen.slice(0, n) });
    /* verder met teksten van hetzelfde niveau en hetzelfde thema (of allebei zonder) */
    var lijst = D.teksten.filter(function(x){ return x.n === heel.n && (x.thema || '') === (heel.thema || ''); }).sort(function(a, b){ return a.id < b.id ? -1 : 1; });
    var i = lijst.map(function(x){ return x.id; }).indexOf(heel.id), zinnen = heel.zinnen.slice();
    for (var k = 1; zinnen.length < n && i >= 0 && k < lijst.length; k++) zinnen = zinnen.concat(lijst[(i + k) % lijst.length].zinnen.slice(0, n - zinnen.length));
    return Object.assign({}, heel, { zinnen: zinnen });
  };
  D.weektekst = function(niveau, datum){
    var n = NIV[niveau] || (typeof niveau === 'number' ? niveau : 2);
    /* alleen de gewone teksten: een tekst met een vakthema erbij zou het rooster van alle weken verschuiven */
    var lijst = D.teksten.filter(function(t){ return t.n === n && !t.thema; }).sort(function(a, b){ return a.id < b.id ? -1 : 1; });
    if (!lijst.length) return null;
    var w = D.isoWeek(datum), t = lijst[(w.jaar * 53 + w.week) % lijst.length];
    /* vanaf week 41 van 2026 de eerste zeven zinnen (tien was te lang voor een les); de weken ervoor houden hun
       korte tekst, anders klopt een oude uitslag niet meer */
    var oud = t.oud && (w.jaar < 2026 || (w.jaar === 2026 && w.week < 41)), aantal = oud ? t.oud : D.WEEKZINNEN;
    if (t.zinnen.length > aantal) t = Object.assign({}, t, { zinnen: t.zinnen.slice(0, aantal) });
    return t;
  };
})(window.DICTEE_OPGAVEN);
